package com.imgmine.launcher67;

import android.content.Context;
import java.io.InputStream;
import java.util.*;
import org.json.JSONArray;
import org.json.JSONObject;

/** Bundled curated Bedrock command templates (assets/commands.json, generated by tools/gen_commands.py). Local only. */
final class Cmds {
    static final class Entry {
        String id, cat, n, c, note, icon;
        boolean cb, warn, daily;
    }

    private static List<Entry> all;

    /** Blocking, first call only; reads the bundled asset once. */
    static synchronized List<Entry> all(Context ctx) {
        if (all != null) return all;
        List<Entry> out = new ArrayList<>();
        try {
            InputStream in = ctx.getAssets().open("commands.json");
            java.io.ByteArrayOutputStream b = new java.io.ByteArrayOutputStream();
            byte[] buf = new byte[8192];
            int r;
            while ((r = in.read(buf)) > 0) b.write(buf, 0, r);
            in.close();
            JSONArray a = new JSONObject(new String(b.toByteArray(), "UTF-8")).getJSONArray("c");
            for (int i = 0; i < a.length(); i++) {
                JSONObject j = a.getJSONObject(i);
                Entry e = new Entry();
                e.id = j.optString("id");
                e.cat = j.optString("cat", "chat");
                e.n = j.optString("n");
                e.c = j.optString("c");
                e.cb = j.optBoolean("cb");
                e.warn = j.optBoolean("warn");
                e.daily=j.optBoolean("daily");
                e.note = j.optString("note", "");
                e.icon = j.optString("icon", "ic_misc");
                out.add(e);
            }
        } catch (Exception ignored) { }
        all = out;
        return out;
    }

    static Addon toAddon(Entry e) {
        Addon a = new Addon();
        a.id = e.id;
        a.type = "command";
        a.name = e.n;
        a.desc = e.c;
        a.page = e.icon;
        a.cmd = e;
        a.lname = Fuzzy.norm(e.n);
        a.ldesc = Fuzzy.norm(e.c);
        return a;
    }
}
